import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"GFX","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/gfx.md","filePath":"03-developer/models/gfx.md"}`),a={name:`03-developer/models/gfx.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="gfx" tabindex="-1">GFX <a class="header-anchor" href="#gfx" aria-label="Permalink to “GFX”">​</a></h1><p>Manages the site&#39;s visual and appearance settings. These settings are created by the initial Seeder and used by different parts of the template, including Theme and Segment. The settings&#39; values are available as CSS variables in <code>client.scss</code>, allowing different parts of the site to follow a shared set of settings.</p><p>The initial records are created by the Seeder. In the current workflow, existing settings are edited; settings are not added or removed during normal use of the system.</p><h2 id="gfxes-table" tabindex="-1"><code>gfxes</code> table <a class="header-anchor" href="#gfxes-table" aria-label="Permalink to “gfxes table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique setting ID</td></tr><tr><td><code>key</code></td><td>VARCHAR(255)</td><td>No</td><td>Unique setting key used to access its value in code; for example, <code>background</code></td></tr><tr><td><code>label</code></td><td>VARCHAR(255)</td><td>No</td><td>Display title for the setting; for example, <code>Primary color</code></td></tr><tr><td><code>system</code></td><td>TINYINT(1)</td><td>No</td><td>System setting indicator; its precise purpose in the current logic is not yet clear</td></tr><tr><td><code>value</code></td><td>LONGTEXT</td><td>No</td><td>Graphic setting value</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Date of last update</td></tr></tbody></table><h2 id="initial-settings" tabindex="-1">Initial settings <a class="header-anchor" href="#initial-settings" aria-label="Permalink to “Initial settings”">​</a></h2><p>The following values are created by the Seeder:</p><table tabindex="0"><thead><tr><th><code>key</code></th><th><code>label</code></th><th>Initial value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>background</code></td><td><code>background color</code></td><td><code>#eeeeee</code></td><td>Background color</td></tr><tr><td><code>primary</code></td><td><code>Primary color</code></td><td><code>#03b2b5</code></td><td>Template primary color</td></tr><tr><td><code>secondary</code></td><td><code>Secondary color</code></td><td><code>#0064c2</code></td><td>Template secondary color</td></tr><tr><td><code>text</code></td><td><code>Text color</code></td><td><code>#111111</code></td><td>Text color</td></tr><tr><td><code>dark</code></td><td><code>Theme mode</code></td><td><code>0</code></td><td>Sets the template&#39;s visual mode</td></tr><tr><td><code>border-radius</code></td><td><code>Border radius</code></td><td><code>7px</code></td><td>Corner radius</td></tr><tr><td><code>shadow</code></td><td><code>Shadow</code></td><td><code>2px 2px 4px #777777</code></td><td>Shadow setting</td></tr><tr><td><code>container</code></td><td><code>Container</code></td><td><code>container</code></td><td>Value corresponding to the Container class or type</td></tr><tr><td><code>font</code></td><td><code>font</code></td><td><code>Vazirmatn</code></td><td>Template font</td></tr></tbody></table><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to “Usage”">​</a></h2><ul><li><strong><code>key</code>:</strong> The unique text identifier for a setting, making it easier to access; for example, searching by <code>key = background</code> instead of relying on the record&#39;s numeric ID.</li><li><strong><code>label</code>:</strong> The setting&#39;s title, which can be displayed in the management interface.</li><li><strong><code>value</code>:</strong> Stores the editable setting value. The value&#39;s type depends on the setting; for example, colors are stored as color codes, corner radii as CSS values, and fonts as font names.</li><li><strong>CSS variables:</strong> Setting values are made available to the template as CSS variables in <code>client.scss</code>, allowing Theme and Segment to use them.</li><li><strong><code>system</code>:</strong> This field exists in the table structure, but its precise meaning and its effect on whether settings can be edited or managed cannot be determined from the available information.</li></ul><h2 id="design-notes" tabindex="-1">Design notes <a class="header-anchor" href="#design-notes" aria-label="Permalink to “Design notes”">​</a></h2><ul><li>The <code>key</code> field has a uniqueness constraint, so each setting must have a distinct key.</li><li>Initial settings are provided by the Seeder, and changing their values is the standard way to customize the site&#39;s appearance.</li><li>The <code>value</code> field is of type <code>LONGTEXT</code> so it can store text values in different formats.</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};